<?php

namespace App\Models;

use App\Support\Lookups;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Carbon;

/**
 * `drivers` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $DriverID
 * @property string|null $Fullname
 * @property string|null $LicenceNumber
 * @property string|null $IDNumber
 * @property int|null $UserID
 * @property string|null $Files
 * @property string|null $MobilePhone
 * @property string|null $Email
 * @property Carbon|null $StartDate
 * @property Carbon|null $EndDate
 * @property string|null $ContractType
 * @property string|null $LicenceType
 * @property float|null $Salary
 * @property float|null $Benefits
 * @property int|null $Active
 * @property string|null $Shortname
 * @property int|null $CalOrder
 * @property int|null $Flag
 * @property int|null $TelegramID
 * @property string|null $CalColor name colour on the drivers calendar (added for the new app)
 */
class Driver extends Model
{
    protected $table = 'drivers';

    protected $primaryKey = 'DriverID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'DriverID' => 'integer',
            'UserID' => 'integer',
            'StartDate' => 'date',
            'EndDate' => 'date',
            'Salary' => 'float',
            'Benefits' => 'float',
            'Active' => 'integer',
            'CalOrder' => 'integer',
            'Flag' => 'integer',
            'TelegramID' => 'integer',
        ];
    }

    protected static function booted(): void
    {
        static::saved(fn () => Lookups::flush());
    }
}
